#include <bits/stdc++.h>
using namespace std;

const int MAXN=1e6+5;
const int MODA=998244353;
const int MODB=1e9+7;
const int BASE=1000000;

long long n;
vector<int> digits[10];
long long counter=0;
int prefixSum[10];
int totalAnswer=0;

void buildSequences(int level,int value){
    digits[level].push_back(((++counter)-value+MODA)%MODA);
    prefixSum[level]+=digits[level].back()%MODB;
    prefixSum[level]%=MODB;
    if(level==6) return;
    for(int i=0;i<=9;i++) buildSequences(level+1,10*value+i);
}

void processSequences(long long x){
    if(x>n) return;
    if(x*BASE+BASE-1<=n && x*BASE*10>n){
        long long rk=counter;
        for(int i=0,step=1;i<=6;i++,step*=10){
            int delta=((rk - x*step)%MODA+MODA)%MODA;
            int pos=lower_bound(digits[i].begin(),digits[i].end(),-delta+MODA)-digits[i].begin();
            totalAnswer+=((1LL*delta*digits[i].size()%MODB+prefixSum[i])%MODB - 1LL*(digits[i].size()-pos)*MODA%MODB +MODB)%MODB;
            totalAnswer%=MODB;
            counter+=digits[i].size();
        }
        return;
    }
    totalAnswer+=(((++counter)-x)%MODA+MODA)%MODA;
    totalAnswer%=MODB;
    for(int i=0;i<=9;i++) processSequences(x*10+i);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n;
    buildSequences(0,0);
    for(int i=0;i<=6;i++) sort(digits[i].begin(),digits[i].end());
    counter=0;
    for(int i=1;i<=9;i++) processSequences(i);
    cout << totalAnswer << "\n";
    return 0;
}
